from __future__ import annotations

import hashlib
from datetime import datetime
from typing import Callable

from secretscan.model import Confidence, Finding, Module, Severity
from secretscan.redact import context as redact_context
from secretscan.redact import hash_file, hash_value
from secretscan.redact import value as redact_value
from secretscan.redact import value_with_length_hint
from secretscan.rules.placeholder import looks_like_placeholder
from secretscan.rules.rule import CompiledRule, Match

MAX_SCAN_LINE_BYTES = 1 << 20  # 1MB


def fingerprint(rule_id: str, secret_hash: str, file_path: str) -> str:
    raw = f"{rule_id}|{secret_hash}|{file_path}"
    return hashlib.sha256(raw.encode()).hexdigest()[:16]


def _truncate(s: str, n: int) -> str:
    return s[:n] + "..." if len(s) > n else s


def to_finding(
    rule: CompiledRule,
    m: Match,
    line: str,
    location: str,
    line_num: int,
    module: Module,
    reveal_length: bool,
) -> Finding:
    h = hash_value(m.secret)
    file_identity = False

    if rule.rule.is_file_identity() and module == Module.FILESYSTEM:
        try:
            h = hash_file(location)
            file_identity = True
        except OSError:
            pass

    if rule.rule.is_file_identity():
        display_value = m.secret
        display_context = _truncate(line, 240)
    else:
        display_value = value_with_length_hint(m.secret, reveal_length)
        display_context = redact_context(_truncate(line, 240), m.secret)

    placeholder = not rule.rule.is_file_identity() and looks_like_placeholder(m.secret)
    severity = Severity(rule.rule.severity)
    if placeholder:
        severity = Severity.LOW

    loc = location
    if line_num > 0:
        loc = f"{location}:{line_num}"

    confidence = Confidence.MEDIUM if rule.rule.entropy_enabled else Confidence.HIGH

    return Finding(
        fingerprint=fingerprint(rule.rule.id, h, location),
        rule_id=rule.rule.id,
        description=rule.rule.description,
        severity=severity,
        confidence=confidence,
        module=module,
        file_path=location,
        location=loc,
        redacted_value=display_value,
        redacted_context=display_context,
        secret_hash=h,
        tags=list(rule.rule.tags),
        detected_at=datetime.utcnow(),
        file_identity=file_identity,
        placeholder=placeholder,
    )


def scan_lines(
    lines: list[str],
    rules: list[CompiledRule],
    location: str,
    module: Module,
    emit: Callable[[Finding], None],
    reveal_length: bool = False,
    allow_matcher: Callable[[str], bool] | None = None,
) -> None:
    for line_num, line in enumerate(lines, 1):
        if not line:
            continue
        if len(line.encode("utf-8", errors="replace")) > MAX_SCAN_LINE_BYTES:
            line = line[:MAX_SCAN_LINE_BYTES]
        lower_line = line.lower()
        for rule in rules:
            if rule.quick_reject(lower_line):
                continue
            for m in rule.find_all(line):
                if allow_matcher and allow_matcher(m.secret):
                    continue
                emit(to_finding(rule, m, line, location, line_num, module, reveal_length))
